//! Progress builder and tracker types.

/// Builds a percentage string from a progress/total pair.
///
/// Mirrors `indicators::ProgressBuilder`: `set_progress(60).set_total(200)`
/// followed by `build()` yields `"30.0%"`.
#[derive(Debug, Default, Clone)]
pub struct ProgressBuilder {
    progress: u64,
    total: u64,
}

impl ProgressBuilder {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn set_progress(&mut self, progress: u64) -> &mut Self {
        self.progress = progress;
        self
    }

    pub fn set_total(&mut self, total: u64) -> &mut Self {
        self.total = total;
        self
    }

    /// Renders `progress / total` as a percentage with one decimal place,
    /// e.g. `"30.0%"`.
    pub fn build(&self) -> String {
        let pct = if self.total == 0 {
            0.0
        } else {
            self.progress as f64 / self.total as f64 * 100.0
        };
        format!("{:.1}%", pct)
    }
}

/// Tracks progress across a sequence of named stages.
///
/// Mirrors `indicators::ProgressTracker`: stages are registered with
/// `add_stage`, and progress/total are set independently.
/// `get_progress()` renders `"current/total"` and `get_percentage()`
/// renders the ratio as a one-decimal percentage.
#[derive(Debug, Default, Clone)]
pub struct ProgressTracker {
    stages: Vec<String>,
    progress: u64,
    total: u64,
}

impl ProgressTracker {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn add_stage(&mut self, stage: &str) -> &mut Self {
        self.stages.push(stage.to_string());
        self
    }

    pub fn set_progress(&mut self, progress: u64) -> &mut Self {
        self.progress = progress;
        self
    }

    pub fn set_total(&mut self, total: u64) -> &mut Self {
        self.total = total;
        self
    }

    /// Returns `"current/total"`, e.g. `"1/3"`.
    pub fn get_progress(&self) -> String {
        format!("{}/{}", self.progress, self.total)
    }

    /// Returns the ratio as a percentage with one decimal place,
    /// e.g. `"33.3%"`.
    pub fn get_percentage(&self) -> String {
        let pct = if self.total == 0 {
            0.0
        } else {
            self.progress as f64 / self.total as f64 * 100.0
        };
        format!("{:.1}%", pct)
    }
}

