//! String formatting helpers.

/// Mirrors `indicators::Format`.
pub struct Format;

impl Format {
    /// Formats a fractional value (0.0–1.0) as a percentage string.
    ///
    /// `percentage(0.33)` yields `"33.0%"` (one decimal by default);
    /// `percentage_precision(0.66, 2)` yields `"66.00%"`.
    pub fn percentage(value: f32) -> String {
        Self::percentage_precision(value, 1)
    }

    pub fn percentage_precision(value: f32, precision: usize) -> String {
        format!("{:.*}%", precision, value as f64 * 100.0)
    }
}

