//! The program takes no command-line arguments (matching the C++ binary)
//! and prints, in order:
//!   - a `ProgressBuilder`-built percentage string,
//!   - a tracker's `"current/total"` progress,
//!   - the tracker's percentage,
//!   - two `Format::percentage` outputs.

#[path = "src/lib.rs"]
mod indicators;

use indicators::{Format, ProgressBuilder, ProgressTracker};

fn main() {
    let mut builder = ProgressBuilder::new();
    builder.set_progress(60).set_total(200);
    println!("{}", builder.build());

    let mut tracker = ProgressTracker::new();
    tracker
        .add_stage("Downloading")
        .add_stage("Processing")
        .add_stage("Saving");
    tracker.set_progress(1);
    tracker.set_total(3);
    println!("{}", tracker.get_progress());
    println!("{}", tracker.get_percentage());

    println!("{}", Format::percentage(0.33f32));
    println!("{}", Format::percentage_precision(0.66f32, 2));
}

